const std = @import("std");

pub fn main() !void {
    const text = "Hello, Zig!";
    const shift: u8 = 3;

    std.debug.print("Original: {s}\n", .{text});
    std.debug.print("Encrypted: ", .{});
    for (text) |ch| {
        if (ch >= 'a' and ch <= 'z') {
            std.debug.print("{c}", .{((ch - 'a' + shift) % 26) + 'a'});
        } else if (ch >= 'A' and ch <= 'Z') {
            std.debug.print("{c}", .{((ch - 'A' + shift) % 26) + 'A'});
        } else {
            std.debug.print("{c}", .{ch});
        }
    }
    std.debug.print("\n", .{});
}
